/**
 * The one surface this page shows when there is no room to render: still
 * loading, server unreachable, or a room the server says does not exist.
 *
 * These three used to be one case, and it was the loaded one. The page held its
 * seats, spectators and chat in module-level constants, so it rendered a
 * complete room with the backend stopped -- a screenshot of it proved nothing
 * about the wiring, and a person could not tell a dead server from a live one.
 *
 * `api.getRoom` resolves null for a 404 *and* for a refused connection, and the
 * three collection routes resolve [] for both, so the reachability probe is the
 * only thing that can separate "this room is gone" from "I could not ask".
 */
function roomStatus({ loading, unreachable, roomId, onRetry, onBack }: {
  loading: boolean;
  unreachable: boolean;
  roomId: number;
  onRetry: () => void;
  onBack: () => void;
}) {
  if (loading) {
    return (
      <UI.EmptyState
        icon="loader"
        title="正在读取房间…"
        body={`正在向服务器请求 /v1/rooms/${roomId}`}
      />
    );
  }
  if (unreachable) {
    return (
      <UI.EmptyState
        icon="wifi-off"
        title="读不到这个房间"
        body="连不上服务器。下面这些列表可能是空的，也可能只是没读到。"
        action={
          <BtnR variant="primary" size="md" onClick={onRetry}>
            <Lu name="refresh-cw" size={12} />
            <span className="cjk" style={{ marginLeft: 6 }}>重试</span>
          </BtnR>
        }
      />
    );
  }
  return (
    <UI.EmptyState
      icon="door-open"
      title={`房间 #${roomId} 不存在`}
      body="服务器回答了，但它手上没有这个房间。"
      action={
        <BtnR variant="secondary" size="md" onClick={onBack}>
          <span className="cjk">返回大厅</span>
        </BtnR>
      }
    />
  );
}

