/**
 * Read-only display of a match parameter.
 *
 * Every control in this panel used to render as an enabled button with no
 * `onClick`: difficulty, mode, max lives, max bombs, the seed reroll, and the
 * visibility dropdown. They looked editable, so a host clicked them, nothing
 * happened, and the page never said why. Persisting any of them needs
 * `PATCH /v1/rooms/{id}`, which the server does not implement (its room router
 * mounts only the four GETs — listRooms, getRoom, listSeats, listSpectators).
 * So they now say exactly that when clicked, instead of silently doing
 * nothing. When the route lands, `readOnly` is the one thing to flip.
 */
function DiffRadio({ value, onBlocked }: { value: Difficulty; onBlocked?: () => void }) {
  return (
    <div style={{ display: 'inline-flex', gap: 4, flexWrap: 'wrap' }}>
      {['Easy','Normal','Hard','Lunatic','Extra'].map(o => (
        <button key={o} title={value === o ? `当前难度 ${o}` : `改为 ${o}`} onClick={onBlocked} className="btn-pressable" style={{
          height: 24, paddingInline: 9, borderRadius: 6, border: '1px solid',
          background: value === o ? 'var(--bg-3)' : 'var(--bg-2)',
          borderColor: value === o ? 'var(--border-strong)' : 'var(--border)',
          color: value === o ? 'var(--fg-0)' : 'var(--fg-2)',
          fontSize: 11, fontWeight: 600, fontFamily: 'var(--font-mono)', cursor: 'pointer',
        }}>{o}</button>
      ))}
    </div>
  );
}

/**
 * A match parameter the server has no field for.
 *
 * `Room` (src/lib/api/types.ts is the contract) carries id, gameId, kind,
 * title, host, region, ping, diff, mode, taken, total, vis, state and endpoint
 * — nothing else about a match exists to render. So this row says exactly
 * that, with the specific route or measurement that would make it show a
 * value, instead of printing a number.
 *
 * Every row it replaces was a literal behind a control: `3` lives, `3` bombs,
 * `0x4F2A91C7` behind a reroll button, `Full Cone` with a green dot, `1492`,
 * `60 Hz`, `10s`, `SHA256:af3c…91d2`, `已通过`, `20:58:14`, `98 / 100`. A host
 * clicked them and read back a value the server had never seen, and a player
 * who probed the port learned we were making it up.
 */
function ParamMissing({ why }: { why: string }) {
  return (
    <Unavailable reason={why}>
      <span className="num" style={{ fontSize: 11.5, color: 'var(--fg-3)' }}>—</span>
    </Unavailable>
  );
}

/** What a parameter that only a server field could carry would need. */
const NEEDS_ROOM_FIELD = (field: string) =>
  `Room 里没有 ${field} 字段（src/lib/api/types.ts 是这份契约的唯一真源），服务端也没有对应的列。要显示它并允许修改，需要 PATCH /v1/rooms/{id}。`;

/** What a parameter the client has to measure itself would need. */
const NOT_MEASURED = (what: string) =>
  `${what}——客户端没有任何代码测量它，服务端也没有这个字段，所以这里没有可显示的值。`;

const SEED_NOT_READABLE =
  '随机种子由 DLL 在握手时自己抽（dll/src/net/lockstep.cpp：读 TH08_PLATFORM_SEED，没有就用 GetTickCount64() 与进程号异或），只走 THP 的 START 包，不经过服务端。客户端读不到它，也无法重掷。';

function ParamPanel({ room, onBlocked }: { room: Room; onBlocked?: (what: string) => void }) {
  const [tab, setTab] = useStateR('basic');
  return (
    <div style={{ background: 'var(--bg-1)', border: '1px solid var(--border)', borderRadius: 'var(--r-lg)', display: 'flex', flexDirection: 'column', height: '100%' }}>
      <div style={{ padding: '14px 16px 0' }}>
        <div className="cjk h-display-sm" style={{ color: 'var(--fg-0)', marginBottom: 10 }}>对局参数</div>
        <TabsR dense
          tabs={[{id:'basic',label:<span className="cjk">基础</span>},{id:'adv',label:<span className="cjk">进阶</span>},{id:'net',label:<span className="cjk">网络</span>},{id:'ac',label:<span className="cjk">反作弊</span>}]}
          active={tab} onChange={setTab} />
      </div>
      <div style={{ padding: '6px 16px 16px', overflowY: 'auto' }}>
        {tab === 'basic' && (<>
          <ParamRowR label="难度"><DiffRadio value={room.diff} onBlocked={() => onBlocked && onBlocked('难度')} /></ParamRowR>
          <ParamRowR label="模式">
            <button title="切换模式" onClick={() => onBlocked && onBlocked('模式')} className="btn-pressable" style={{ height: 26, paddingInline: 10, gap: 6, borderRadius: 6, border: '1px solid var(--border)', background: 'var(--bg-2)', color: 'var(--fg-0)', fontSize: 11.5, fontWeight: 600, cursor: 'pointer', display: 'inline-flex', alignItems: 'center' }}><span className="cjk">{room.mode}</span><Lu name="chevron-down" size={12} /></button>
          </ParamRowR>
          <ParamRowR label="最大 Lives"><ParamMissing why={NEEDS_ROOM_FIELD('lives')} /></ParamRowR>
          <ParamRowR label="最大 Bombs"><ParamMissing why={NEEDS_ROOM_FIELD('bombs')} /></ParamRowR>
          <ParamRowR label="随机种子"><ParamMissing why={SEED_NOT_READABLE} /></ParamRowR>
        </>)}
        {tab === 'net' && (<>
          {/* Four spans — P2P 直连 / Relay / LAN / FRP — with the first one
              highlighted. They read as a choice, they are not buttons, and no
              route reports a transport. What is true is the single line below:
              the client dials the address the room publishes, over plain UDP,
              and only once the host has published one. */}
          <ParamRowR label="连接方式">
            <span className="num" style={{ fontSize: 11.5, color: room.endpoint ? 'var(--fg-0)' : 'var(--fg-3)' }}>
              {room.endpoint ? `P2P 直连 ${peerAddr(room.endpoint)}` : '未公布'}
            </span>
          </ParamRowR>
          <ParamRowR label="NAT 类型"><ParamMissing why={NOT_MEASURED('NAT 类型要靠 STUN 或服务端探测 UDP 打洞结果才能知道')} /></ParamRowR>
          <ParamRowR label="当前 RTT"><span className="num" style={{ fontSize: 11.5, color: 'var(--fg-0)', fontWeight: 600 }}>{room.ping} ms</span></ParamRowR>
          <ParamRowR label="MTU"><ParamMissing why={NOT_MEASURED('路径 MTU 由操作系统与链路协商决定，客户端从不读取')} /></ParamRowR>
          {/* The transport is plaintext UDP. `dll/src/net/protocol.h` — the
              fixed 152-byte `Pack` this comment used to cite — no longer
              exists: `dll/src/net/thp_session.h` documents its deletion and its
              replacement by the versioned THP protocol, and there is no
              cryptography anywhere in dll/src. Do not label this AES-256-GCM or
              any cipher: a player who probes the port learns we lie, and then
              nothing else we say is worth anything. Say what is true — the peer
              is trusted, and the payload is not confidential. */}
          <ParamRowR label="加密"><span className="num" style={{ fontSize: 10.5, color: 'var(--fg-1)', padding: '2px 6px', background: 'var(--bg-2)', border: '1px solid var(--border)', borderRadius: 4 }}>无</span></ParamRowR>
        </>)}
        {tab === 'ac' && (<>
          <ParamRowR label="DLL 签名"><ParamMissing why={NOT_MEASURED('客户端跑在 WebView 里，读不到注入的 DLL 文件，也算不出它的 SHA-256；服务端没有校验接口')} /></ParamRowR>
          <ParamRowR label="哈希校验"><ParamMissing why={NOT_MEASURED('没有任何代码比对哈希，这条结论没有来源')} /></ParamRowR>
          <ParamRowR label="最近注入"><ParamMissing why="注入时刻只写进桌面壳的注入日志，客户端没有读日志的命令：src-tauri 只暴露 launch_game 与 terminate_game。" /></ParamRowR>
          <ParamRowR label="完整性评分"><ParamMissing why={NOT_MEASURED('没有任何评分算法，这条分数没有来源')} /></ParamRowR>
        </>)}
        {tab === 'adv' && (<>
          <ParamRowR label="自机机型 锁定"><ParamMissing why={NEEDS_ROOM_FIELD('自机机型锁定')} /></ParamRowR>
          <ParamRowR label="符卡同步频率"><ParamMissing why={NOT_MEASURED('lockstep 跟随游戏帧推进，客户端没有可配置的同步频率')} /></ParamRowR>
          <ParamRowR label="掉线宽限"><ParamMissing why={NOT_MEASURED('掉线宽限由 DLL 的 KEEPALIVE 判定，不经过客户端')} /></ParamRowR>
          <ParamRowR label="允许中途加入"><ParamMissing why={NEEDS_ROOM_FIELD('中途加入策略')} /></ParamRowR>
        </>)}
      </div>
    </div>
  );
}

