function RoomBottomBar({ state = 'lobby', readyCount = 0, lastMessage, roomId, onStart, onLeave }: { state?: RoomState; readyCount?: number; lastMessage?: ChatMsg; roomId: number; onStart?: () => void; onLeave?: () => void }) {
  // NOTE: the router only ever produces 'lobby' | 'post' (src/router/index.tsx),
  // so the 'loading' arm below is unreachable today. It stays because
  // `RoomState` is the domain's own union and a server poll is what will start
  // feeding it — not because anything reaches it now.
  const cta = state === 'loading' ? { label: '正在加载…', spin: true, disabled: true, glow: false }
    : state === 'post' ? { label: '再来一局 REMATCH', glow: false }
    : { label: `开始对局 START · ${readyCount} ready`, glow: true };
  return (
    <div style={{ height: 76, paddingInline: 18, display: 'flex', alignItems: 'center', gap: 14, borderTop: '1px solid var(--border)', background: 'var(--bg-0)' }}>
      <div style={{ flex: 1, minWidth: 0, height: 44, background: 'var(--bg-1)', border: '1px solid var(--border)', borderRadius: 'var(--r-md)', paddingInline: 12, display: 'flex', alignItems: 'center', gap: 10, cursor: 'pointer' }}>
        {lastMessage ? (<>
          <AvR size={24} name={lastMessage.who ?? ''} />
          <div style={{ minWidth: 0, flex: 1 }}>
            <div className="cjk t-caption" style={{ color: 'var(--fg-2)' }}><span style={{ color: 'var(--fg-1)', fontWeight: 600 }}>{lastMessage.who}</span> · {lastMessage.t}</div>
            <div className="cjk t-body" style={{ color: 'var(--fg-1)', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>
              {lastMessage.msg}
            </div>
          </div>
        </>) : (
          <div className="cjk t-caption" style={{ color: 'var(--fg-3)' }}>还没有人说话</div>
        )}
        <span className="num" style={{ fontSize: 10, color: 'var(--fg-3)' }}>展开 #room-{roomId} →</span>
      </div>
      <button onClick={onStart} disabled={cta.disabled} className={`btn-pressable ${cta.glow ? 'anim-cta-glow' : ''}`} style={{ minWidth: 220, height: 44, paddingInline: 22, borderRadius: 'var(--r-md)', background: 'var(--accent)', color: 'var(--bg-0)', border: '1px solid var(--accent)', fontSize: 13, fontWeight: 700, cursor: cta.disabled ? 'not-allowed' : 'pointer', opacity: cta.disabled ? 0.55 : 1, display: 'inline-flex', alignItems: 'center', justifyContent: 'center', gap: 8, fontFamily: 'var(--font-sans)' }}>
        {cta.spin ? <span className="spinner" style={{ width: 12, height: 12, border: '2px solid rgba(0,0,0,0.25)', borderTopColor: 'var(--bg-0)', borderRadius: '50%' }} /> : null}
        <span className="cjk">{cta.label}</span>
      </button>
      <button onClick={onLeave} className="btn-pressable" style={{ height: 44, paddingInline: 14, borderRadius: 'var(--r-md)', background: 'transparent', border: '1px solid var(--border-strong)', color: 'var(--fg-1)', fontSize: 12.5, fontWeight: 600, cursor: 'pointer' }}><span className="cjk">离开房间</span></button>
    </div>
  );
}

function ChatDrawerR({ roomId, chat, sysLog, unreachable, roomLoaded, onSent, onFailed }: { roomId: number; chat: ChatMsg[]; sysLog: ChatMsg[]; unreachable: boolean; roomLoaded: boolean; onSent?: (msg: unknown) => void; onFailed?: (channelId: string, error: unknown) => void }) {
  return (
    <aside className="thp-col-aside" style={{ width: 320, background: 'var(--bg-1)', borderLeft: '1px solid var(--border)', display: 'flex', flexDirection: 'column' }}>
      <div style={{ padding: '12px 14px', borderBottom: '1px solid var(--border)', display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
        <div>
          <div style={{ fontSize: 12.5, fontWeight: 700, color: 'var(--fg-0)' }}># room-{roomId}</div>
          <div className="cjk t-caption" style={{ color: 'var(--fg-2)' }}>房间私聊</div>
        </div>
        <button className="btn-pressable" style={{ width: 24, height: 24, borderRadius: 6, border: 'none', background: 'transparent', color: 'var(--fg-2)', cursor: 'pointer', display: 'inline-flex', alignItems: 'center', justifyContent: 'center' }}><Lu name="x" size={14} /></button>
      </div>
      {sysLog.length > 0 && (
      <div style={{ margin: 12, padding: 10, borderRadius: 'var(--r-md)', background: 'var(--bg-2)', border: '1px solid var(--border)' }}>
        <div className="t-tag" style={{ color: 'var(--fg-2)' }}>对局信息 · 最近 {sysLog.length} 条</div>
        <div style={{ display: 'flex', flexDirection: 'column', gap: 4, marginTop: 8 }}>
          {sysLog.map((m, i) => (
            <div key={i} className="cjk t-caption" style={{ color: 'var(--fg-1)', display: 'flex', gap: 8 }}>
              <span className="num" style={{ color: 'var(--fg-3)', fontSize: 10 }}>{m.t}</span><span>{m.text}</span>
            </div>
          ))}
        </div>
      </div>
      )}
      <div style={{ flex: 1, overflowY: 'auto', padding: '4px 12px 8px', display: 'flex', flexDirection: 'column', gap: 8 }}>
        {chat.length === 0 ? (
          <div style={{ flex: 1, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
            <UI.EmptyState
              icon="message-square"
              title={!roomLoaded ? '房间未载入' : unreachable ? '读不到聊天记录' : '还没有人说话'}
              body={!roomLoaded
                ? '这个房间还没有载入，聊天记录读不了。'
                : unreachable
                  ? '连不上服务器，房间消息可能已经在路上了。'
                  : '房间里现在没有人打字。'}
            />
          </div>
        ) : chat.map((m, i) => {
          if (m.kind === 'sys') return (
            <div key={i} className="cjk t-caption" style={{ color: 'var(--fg-3)', textAlign: 'center', padding: '4px 0' }}>
              <span className="num" style={{ marginRight: 6 }}>{m.t}</span>{m.text}
            </div>
          );
          if (m.kind === 'embed') return (
            <div key={i} style={{ marginLeft: 38, marginTop: 6 }}>
              <SHARED.ServerCardFlat compact {...m.share} onJoin={() => {}} />
            </div>
          );
          const prev = chat[i-1];
          const samegroup = prev && prev.kind !== 'sys' && prev.who === m.who;
          return <CMR key={i} msg={m} samegroup={samegroup} />;
        })}
      </div>
      <ChatComposer
        channelId={`room-${roomId}`}
        placeholder={`发个消息到 #room-${roomId}`}
        onSent={onSent}
        onFailed={onFailed}
      />
    </aside>
  );
}

/**
 * The post-match card.
 *
 * It used to render a finished game that never happened: `21:42:08 · 用时
 * 18:24`, `妖梦 通关 永夜抄 2 面`, `魔理沙·B装备 · Lunatic · 3 lives`, a score of
 * `4,128,920,470`, `Lives / Death 2 / 1`, and four spell cards with their own
 * timestamps and try counts — every field a literal, identical for every room
 * and every player, on a route (`#/room/{id}?state=post`) that a player reaches
 * by editing the URL.
 *
 * There is no result type in src/lib/api/types.ts and no result route on the
 * server, so there is nothing here to render. The card keeps its two real
 * actions and says what is missing.
 */
function ResultsCard({ onRematch, onBack }: { onRematch?: () => void; onBack?: () => void }) {
  return (
    <div className="anim-modal-in" style={{ maxWidth: 540, margin: '24px auto', background: 'var(--bg-1)', border: '1px solid var(--border)', borderRadius: 'var(--r-lg)', padding: 26 }}>
      <span className="t-tag" style={{ color: 'var(--accent)' }}>SESSION ENDED</span>
      <h2 className="cjk h-display-lg" style={{ margin: '6px 0 0' }}>没有这一局的结算数据</h2>
      <UnavailablePanel
        title="结算还没有数据来源"
        missing={<>需要服务端为一场对局落库并下发结果：<span className="num">GET /v1/rooms/{'{id}'}/results</span> 一类的接口，以及 <span className="num">src/lib/api/types.ts</span> 里的一个 <span className="num">MatchResult</span>（得分、用时、剩余残机、通关面数与关键符卡）。目前这两样都不存在，<span className="num">Room</span> 只带 <span className="num">state</span>，不带结果——所以这里不显示任何分数。</>}
      />
      <div style={{ display: 'flex', gap: 8, marginTop: 20 }}>
        <BtnR variant="primary" size="lg" style={{ flex: 1 }} onClick={onRematch}><span className="cjk">再来一局</span></BtnR>
        <BtnR variant="secondary" size="lg" style={{ flex: 1 }} onClick={onBack}><span className="cjk">返回房间席位</span></BtnR>
      </div>
    </div>
  );
}

type RoomProps = {
  theme?: 'dark' | 'light';
  state?: 'lobby' | 'post';
  id?: number;
  onNavigate?: (target: NavTarget) => void;
  onToast?: (msg: { tone?: string; title: string; body?: string }) => void;
};

function Room({ theme = 'dark', state = 'lobby', id = 4912, onNavigate, onToast }: RoomProps) {
  const nav = (t: NavTarget) => onNavigate && onNavigate(t);
  const stub = (label: string) => onToast && onToast({ tone: 'info', title: label });
  // Every editable match parameter needs `PATCH /v1/rooms/{id}`. The server's
  // room router mounts only four GETs (list, get, seats, spectators), so these
  // used to render as live controls that silently did nothing. Naming the
  // missing route is the honest answer, and it is one toast, not a redesign.
  const needsRoomPatch = (what: string) => onToast && onToast({
    tone: 'warn',
    title: `${what}暂时改不了`,
    body: '服务端还没有 PATCH /v1/rooms/{id}，房间参数目前是只读的。',
  });

  // One fetch for the page, four routes. They are the same room, so splitting
  // them across four useAsync calls would let the header render from one
  // response and the seat grid from another.
  const { data, isLoading, refetch } = useAsync(async () => {
    const [room, seats, spectators, chat] = await Promise.all([
      api.getRoom(id),
      api.getRoomSeats(id),
      api.getRoomSpectators(id),
      api.getRoomChat(id),
    ]);
    return { room, seats, spectators, chat };
  }, [id]);

  // `client.ts` resolves a failed collection to [] and a failed room to null
  // without throwing, so an unreachable server and an empty room arrive as the
  // same values. The probe is what lets each empty state say which one it is.
  const unreachable = useBackendReachable() === 'down';
  const { data: me } = useMe();
  const room = data?.room ?? null;
  const seats = data?.seats ?? [];
  const spectators = data?.spectators ?? [];
  const chat = data?.chat ?? [];
  // The sys lines are the room's own event log; the drawer used to show a
  // hardcoded five-line version of the same thing next to the real chat.
  const sysLog = chat.filter((m) => m.kind === 'sys').slice(-5).reverse();
  const lastMessage = [...chat].reverse().find((m) => m.kind !== 'sys' && m.msg);
  const named = seats.filter((s) => s.name);
  const readyCount = named.filter((s) => s.ready).length;
  // START is the only path from a room to a running game. It used to raise a
  // toast, so `launchGame` had no caller at all and the address the server now
  // hands out went nowhere. The launch resolves to a pid or to a message the
  // player can act on; either way it is reported rather than swallowed.
  const [launching, setLaunching] = useStateR(false);
  const startMatch = async () => {
    if (!room || launching) return;
    setLaunching(true);
    try {
      const result = await launchRoomGame(room, seats);
      onToast && onToast({ tone: 'success', title: '游戏已启动', body: `pid ${result.pid}` });
    } catch (err) {
      // A rejected launch can be anything: an Error, a Tauri string, or a
      // structured payload. `instanceof` is the only honest narrowing here;
      // `err?.message` on a non-Error yields undefined and swallowed the reason.
      const why = err instanceof Error ? err.message : String(err);
      onToast && onToast({ tone: 'error', title: '启动失败', body: why });
    } finally {
      setLaunching(false);
    }
  };
  return (
    <div className={`thp theme-${theme} anim-page-in`} style={{ width: '100%', height: '100%', display: 'flex', background: 'var(--bg-0)', overflow: 'hidden', borderRadius: 'var(--r-lg)', position: 'relative' }}>
      <BackendBanner />
      <RailR active="th08" onPick={(p: string) => {
        if (p === 'home') nav({ name: 'lobby' });
        else if (p === 'settings') nav({ name: 'settings' });
        else if (p === 'discover') stub('发现');
        else if (p === 'add-server') stub('添加服务器');
        else nav({ name: 'lobby', gameId: p });
      }} />
      <aside className="thp-col-nav" style={{ width: 240, background: 'var(--bg-1)', borderRight: '1px solid var(--border)', display: 'flex', flexDirection: 'column' }}>
        <div style={{ padding: '12px 14px 10px', borderBottom: '1px solid var(--border)' }}>
          <div className="t-tag" style={{ color: 'var(--fg-2)' }}>当前房间</div>
          <div className="cjk h-display-sm" style={{ color: 'var(--fg-0)', marginTop: 4, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{room ? room.title : '未载入'}</div>
          <div className="num" style={{ fontSize: 10.5, color: 'var(--fg-3)', marginTop: 2 }}>#{id} · {room ? `${room.taken}/${room.total}` : '—'}</div>
        </div>
        <div style={{ padding: 10, overflowY: 'auto', flex: 1, display: 'flex', flexDirection: 'column', gap: 14 }}>
          <div>
            <SLR>本房频道</SLR>
            <div style={{ marginTop: 6 }}>
              {/* One channel, and its id is the one the composer's POST uses:
                  `room-{id}` is what GET /v1/rooms/{id}/chat answers to. The
                  战术讨论 row beside it named a channel no route serves, and
                  clicking it toasted its own name — the client inventing a
                  second room channel out of nothing. */}
              <RowR leading={<span style={{ color: 'var(--fg-2)', fontWeight: 500, fontSize: 14, width: 14, textAlign: 'center' }}>#</span>}>
                <span className="cjk t-body" style={{ fontWeight: 600, color: 'var(--fg-0)' }}>room-{id}</span>
              </RowR>
            </div>
          </div>
          <div>
            <SLR>房间信息</SLR>
            <div style={{ marginTop: 8, padding: 12, background: 'var(--bg-2)', border: '1px solid var(--border)', borderRadius: 'var(--r-md)', display: 'flex', flexDirection: 'column', gap: 6 }}>
              {[
                ['难度', room?.diff ?? '—'],
                ['模式', room?.mode ?? '—'],
                ['区域', room?.region ?? '—'],
                ['可见性', room ? VIS_SHORT[room.vis] ?? room.vis : '—'],
                // The address START will actually dial. Showing it makes a
                // mis-published endpoint visible before anyone launches.
                ['主机地址', room?.endpoint ? peerAddr(room.endpoint) : '未公布'],
              ].map(([k, v]) => (
                <div key={k} style={{ display: 'flex', justifyContent: 'space-between', fontSize: 11 }}>
                  <span className="cjk" style={{ color: 'var(--fg-2)' }}>{k}</span>
                  <span className="num" style={{ color: 'var(--fg-0)', fontWeight: 600 }}>{v}</span>
                </div>
              ))}
            </div>
          </div>
          <div>
            <SLR right={<span className="num" style={{ fontSize: 10, color: 'var(--status-online)' }}>{readyCount} ready</span>}>队伍</SLR>
            <div style={{ marginTop: 6 }}>
              {named.length === 0 ? (
                <div className="cjk t-caption" style={{ color: 'var(--fg-3)', padding: '6px 8px' }}>
                  {!room ? '房间未载入' : unreachable ? '读不到席位' : '还没有人入座'}
                </div>
              ) : named.map((s) => (
                <RowR key={s.idx} onClick={() => stub(`${s.name} 个人主页`)}
                  leading={<AvR size={22} name={s.name ?? ''} status={s.status} />}
                  trailing={s.idx === 1 ? <Lu name="crown" size={11} color="var(--fg-2)" /> : <SDR status={s.ready ? 'online' : 'idle'} />}>
                  <span className="cjk t-body" style={{ color: 'var(--fg-0)' }}>{s.name}</span>
                </RowR>
              ))}
            </div>
          </div>
        </div>
        <IdR me={me ?? null} onSettings={() => nav({ name: 'settings' })} onProfile={() => nav({ name: 'profile' })} />
      </aside>
      <main className="thp-col-main" style={{ display: 'flex', flexDirection: 'column' }}>
        {room
          ? <RoomTopBar room={room} onBack={() => nav({ name: 'lobby' })} onCopy={async () => {
              // This used to fire a "已复制邀请链接" toast without touching the
              // clipboard, so the toast was a lie and the pasted text was
              // whatever the user had copied before. Report the real outcome.
              const ok = await copyToClipboard(currentViewUrl());
              if (!onToast) return;
              onToast(ok
                ? { tone: 'success', title: '已复制邀请链接', body: currentViewUrl() }
                : { tone: 'warn', title: '复制失败', body: '浏览器拒绝了剪贴板写入，请手动复制地址栏的链接。' });
            }} onSettings={() => stub('房间设置')} onVis={() => needsRoomPatch('可见性')} />
          : <div style={{ height: 56, paddingInline: 18, display: 'flex', alignItems: 'center', gap: 14, borderBottom: '1px solid var(--border)', background: 'var(--bg-0)' }}>
              <button onClick={() => nav({ name: 'lobby' })} className="btn-pressable" style={{ height: 28, paddingInline: 10, gap: 6, display: 'inline-flex', alignItems: 'center', background: 'transparent', border: '1px solid var(--border)', borderRadius: 6, color: 'var(--fg-1)', cursor: 'pointer', fontSize: 12, fontWeight: 600 }}><Lu name="arrow-left" size={13} /><span className="cjk">返回大厅</span></button>
              <div style={{ flex: 1, minWidth: 0, textAlign: 'center' }}>
                <div className="cjk h-display-sm" style={{ color: 'var(--fg-3)', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>房间 #{id}</div>
              </div>
              <span style={{ width: 28 }} />
            </div>}
        <div className="thp-room-body" style={{ flex: 1, minHeight: 0, display: 'flex', overflow: 'hidden' }}>
          {!room ? (
            <div style={{ flex: 1, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
              {roomStatus({ loading: isLoading, unreachable, roomId: id, onRetry: refetch, onBack: () => nav({ name: 'lobby' }) })}
            </div>
          ) : state === 'post' ? (
            <div style={{ flex: 1, overflowY: 'auto', background: 'var(--bg-0)' }}>
              <ResultsCard onRematch={() => nav({ name: 'room', id, state: 'lobby' })} onBack={() => nav({ name: 'room', id, state: 'lobby' })} />
            </div>
          ) : (
            <>
              <section className="thp-room-seats" style={{ flex: '1 1 60%', minWidth: 0, padding: '18px 20px', overflowY: 'auto', display: 'flex', flexDirection: 'column', gap: 16 }}>
                <div style={{ display: 'flex', alignItems: 'baseline', justifyContent: 'space-between', gap: 12, flexWrap: 'wrap' }}>
                  <h3 className="cjk h-display-sm" style={{ margin: 0, whiteSpace: 'nowrap' }}>席位 <span className="num" style={{ color: 'var(--fg-2)', fontSize: 12, fontWeight: 600 }}>{named.length}/{seats.length}</span></h3>
                  {/* Was "主机可调整 · 拖拽换位". Nothing is draggable: the seat
                      cards have no drag handler, and reordering would need
                      PATCH /v1/rooms/{id}/seats/{idx}, which the server does not
                      mount. A caption promising a gesture is a promise the
                      client cannot keep. */}
                  <span className="cjk t-caption" style={{ color: 'var(--fg-2)', whiteSpace: 'nowrap' }}>席位顺序由服务端返回 · 暂不可换位</span>
                </div>
                <div className="thp-seat-grid">
                  {seats.length === 0 ? (
                    <UI.EmptyState
                      icon="user-plus"
                      title={unreachable ? '读不到席位' : '这个房间还没有席位'}
                      body={unreachable
                        ? '连不上服务器，席位可能已经在路上了。'
                        : '房间是空的，先邀请几个人进来。'}
                    />
                  ) : seats.map((s, i) => <SeatCard key={s.idx} seat={s} isHost={s.idx === 1} index={i} onPickRole={(role: string) => onToast && onToast({
                      tone: 'warn',
                      title: `${s.name} 暂时改不了身份`,
                      body: `改为「${role}」需要 PATCH /v1/rooms/${id}/seats/${s.idx}，服务端还没有这个接口。`,
                    })} />)}
                </div>
                <div>
                  <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 10 }}>
                    <span className="cjk t-body" style={{ fontWeight: 600, color: 'var(--fg-1)' }}>观战席</span>
                    <span style={{ height: 1, background: 'var(--border)', flex: 1 }} />
                    <span className="num" style={{ fontSize: 10.5, color: 'var(--fg-2)' }}>{spectators.length}</span>
                  </div>
                  {spectators.length === 0 ? (
                    <UI.EmptyState
                      icon="eye"
                      title={unreachable ? '读不到观战名单' : '还没有人观战'}
                      body={unreachable ? '连不上服务器，观战名单可能已经在路上了。' : '把这个房间的链接发出去，就能有人进来围观。'}
                    />
                  ) : (
                  <div style={{ display: 'flex', alignItems: 'center', gap: 6, flexWrap: 'wrap' }}>
                    {spectators.slice(0, 8).map((n, i) => <AvR key={i} size={26} name={n} />)}
                    {spectators.length > 8 && (
                      <span className="num" style={{ height: 26, paddingInline: 9, borderRadius: 999, background: 'var(--bg-2)', border: '1px solid var(--border)', color: 'var(--fg-1)', fontSize: 11, fontWeight: 600, display: 'inline-flex', alignItems: 'center' }}>+{spectators.length - 8}</span>
                    )}
                  </div>
                  )}
                </div>
              </section>
              <section className="thp-room-params" style={{ flex: '1 1 40%', minWidth: 320, padding: '18px 20px 18px 0', overflow: 'hidden' }}>
                <ParamPanel room={room} onBlocked={needsRoomPatch} />
              </section>
            </>
          )}
        </div>
        {room && <RoomBottomBar state={state} readyCount={readyCount} lastMessage={lastMessage} roomId={id} onStart={startMatch} onLeave={() => nav({ name: 'lobby' })} />}
      </main>
      <ChatDrawerR roomId={id} chat={chat} sysLog={sysLog} unreachable={unreachable} roomLoaded={!!room}
        onSent={() => onToast && onToast({ tone: 'success', title: '已发送', body: `#room-${id}` })}
        onFailed={(_channelId: string, error: unknown) => onToast && onToast(sendFailureToast(error))} />
    </div>
  );
}

export { Room };
